mapper.select:
SELECT callback_id FROM sys_im_callback_event WHERE tenant_id = #{tenantId}
  AND (status = 'RECEIVED' OR (status IN ('RETRYABLE', 'PROCESSING') AND claim_until <= NOW()))
ORDER BY callback_id LIMIT #{limit}

SELECT tenant_id, callback_id FROM sys_im_callback_event WHERE callback_id > #{after}
  AND (status = 'RECEIVED' OR (status IN ('RETRYABLE', 'PROCESSING') AND claim_until <= NOW()))
ORDER BY callback_id LIMIT #{limit}
